293	
294	        [Fact]
295	        public async Task CreateOrderAsync_SupplierChangesPriceAfterOrder_OrderItemPriceStaysFrozen()
296	        {
297	            var db = CreateContext();
298	            await SeedOfferAsync(db, "P1", "L1", 19.99m);
299	            var service = new OrderService(db);
300	            var request = new CreateOrderRequestDto("Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com",
301	                [new OrderLineRequestDto("P1", "L1", 1)]);
302	            var result = await service.CreateOrderAsync(request);
303	
304	            var offer = await db.Offers.SingleAsync(o => o.ProductId == "P1" && o.SupplierId == "L1");
305	            offer.Price = 29.99m;
306	            await db.SaveChangesAsync();
