311	
312	        [Fact]
313	        public async Task CreateOrderAsync_EmptyItemsList_RejectsWithEmptyCartAndPersistsNothing()
314	        {
315	            var db = CreateContext();
316	            var service = new OrderService(db);
317	            var request = new CreateOrderRequestDto("Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com", []);
318	
319	            var result = await service.CreateOrderAsync(request);
320	
321	            Assert.Null(result.OrderId);
322	            Assert.Equal("empty-cart", result.RejectionReason);
323	            Assert.Equal(0, await db.Orders.CountAsync());
324	            Assert.Equal(0, await db.OrderItems.CountAsync());
325	        }
326	
327	        [Fact]
328	        public async Task CreateOrderAsync_NullItems_RejectsWithEmptyCartWithoutThrowing()
329	        {
330	            var db = CreateContext();
331	            var service = new OrderService(db);
332	            var request = new CreateOrderRequestDto("Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com", null!);
333	
334	            var result = await service.CreateOrderAsync(request);
335	
336	            Assert.Equal("empty-cart", result.RejectionReason);
337	        }
338	
339	        [Fact]
340	        public async Task CreateOrderAsync_OneInvalidQuantityAmongValidItems_RejectsWholeRequestAndPersistsNothing()
341	        {
342	            var db = CreateContext();
343	            await SeedOfferAsync(db, "P1", "L1", 10m);
344	            await SeedOfferAsync(db, "P2", "L1", 20m);
